package org.ikigaidigital.adapter.out.persistence;

import org.ikigaidigital.TimeDeposit;
import org.ikigaidigital.domain.Withdrawal;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;

import java.util.List;

/** Converts JPA entities to the domain model (generated by MapStruct). */
@Mapper(componentModel = MappingConstants.ComponentModel.SPRING)
interface TimeDepositPersistenceMapper {

    // Uses the public TimeDeposit(int, String, Double, int) constructor; BigDecimal -> Double via doubleValue().
    TimeDeposit toDomain(TimeDepositEntity entity);

    List<TimeDeposit> toDomainDeposits(List<TimeDepositEntity> entities);

    @Mapping(target = "timeDepositId", source = "timeDeposit.id")
    Withdrawal toDomain(WithdrawalEntity entity);

    List<Withdrawal> toDomainWithdrawals(List<WithdrawalEntity> entities);
}
